-- Trip Planner M5: invite by verified email or shareable link; role management.
-- Run ONCE after M1-M4, in your existing development Supabase project.
-- No SMTP provider, auth service role key, third-party email API, or billing required.
-- Security: invitation bearer tokens are generated by the Next.js server; ONLY SHA-256
-- token hashes are stored. Invites must be accepted by confirmed-email users.
begin;

create table public.trip_invitations (
  id uuid primary key default gen_random_uuid(),
  trip_id uuid not null references public.trips(id) on delete cascade,
  created_by uuid not null references auth.users(id) on delete restrict,
  token_hash text not null unique check (token_hash ~ '^[0-9a-f]{64}$'),
  kind text not null check (kind in ('email', 'link')),
  role public.trip_member_role not null check (role <> 'owner'),
  invited_email text,
  max_uses integer not null check (max_uses between 1 and 10),
  used_count integer not null default 0 check (used_count >= 0 and used_count <= max_uses),
  expires_at timestamptz not null,
  revoked_at timestamptz,
  created_at timestamptz not null default now(),
  constraint invitation_email_rules check (
    (kind = 'email' and invited_email is not null and max_uses = 1)
    or (kind = 'link' and invited_email is null)
  )
);

create index trip_invitations_trip_idx on public.trip_invitations(trip_id, created_at desc);

-- Invitation secrets cannot be fetched through PostgREST table APIs.
-- Readable invitation metadata is exposed only through a role-checked RPC below.
alter table public.trip_invitations enable row level security;
revoke all on public.trip_invitations from public, anon, authenticated;

-- Only the trip OWNER can issue invitations. The server generates a high-entropy
-- random token, hashes it, and submits only the hash to this RPC.
create function public.create_trip_invitation(
  p_trip_id uuid,
  p_token_hash text,
  p_kind text,
  p_role text,
  p_email text default null
)
returns uuid language plpgsql security definer set search_path = '' as $$
declare
  v_user_id uuid := (select auth.uid());
  v_email text;
  v_invitation_id uuid;
  v_role public.trip_member_role;
  v_max_uses integer;
begin
  if v_user_id is null or not private.is_trip_owner(p_trip_id) then
    raise exception 'Only the trip owner can invite travelers' using errcode = '42501';
  end if;

  if p_token_hash is null or p_token_hash !~ '^[0-9a-f]{64}$' then
    raise exception 'Invalid invitation token' using errcode = '22023';
  end if;
  if p_kind not in ('email', 'link') or p_kind is null
    or p_role not in ('editor', 'viewer') or p_role is null then
    raise exception 'Invalid invitation type or role' using errcode = '22023';
  end if;
  v_role := p_role::public.trip_member_role;
  v_max_uses := case when p_kind = 'email' then 1 else 10 end;
  v_email := case when p_kind = 'email' then lower(btrim(coalesce(p_email, ''))) else null end;
  if p_kind = 'email' and (
      char_length(v_email) not between 3 and 254
      or v_email !~ '^[^@[:space:]]+@[^@[:space:]]+\.[^@[:space:]]+$'
    ) then
    raise exception 'Enter a valid invitee email address' using errcode = '22023';
  end if;

  -- Prevent unlimited active invitations and serialize simultaneous creations.
  perform 1 from public.trips where id = p_trip_id for update;
  if not found then
    raise exception 'Trip not available' using errcode = '42501';
  end if;
  if (select count(*) from public.trip_invitations i
      where i.trip_id = p_trip_id and i.revoked_at is null
        and i.expires_at > now() and i.used_count < i.max_uses) >= 25 then
    raise exception 'Revoke an active invitation before creating another' using errcode = '22023';
  end if;

  insert into public.trip_invitations
    (trip_id, created_by, token_hash, kind, role, invited_email, max_uses, expires_at)
  values
    (p_trip_id, v_user_id, p_token_hash, p_kind, v_role, v_email, v_max_uses,
     now() + interval '7 days')
  returning id into v_invitation_id;

  return v_invitation_id;
end;
$$;

-- Redeem one invitation once per user, without downgrading existing membership.
-- A lock on the invitation prevents a concurrent last-use double redemption.
create function public.accept_trip_invitation(p_token_hash text)
returns uuid language plpgsql security definer set search_path = '' as $$
declare
  v_user_id uuid := (select auth.uid());
  v_verified_email text;
  v_inv public.trip_invitations%rowtype;
  v_inserted_count integer;
begin
  if v_user_id is null then
    raise exception 'Sign in to accept the invitation' using errcode = '42501';
  end if;
  if p_token_hash is null or p_token_hash !~ '^[0-9a-f]{64}$' then
    raise exception 'Invalid invitation' using errcode = '42501';
  end if;

  select lower(btrim(u.email)) into v_verified_email
  from auth.users u where u.id = v_user_id and u.email_confirmed_at is not null;
  if v_verified_email is null then
    raise exception 'Confirm your email before accepting an invitation' using errcode = '42501';
  end if;

  select * into v_inv from public.trip_invitations
  where token_hash = p_token_hash for update;
  if not found or v_inv.revoked_at is not null
    or v_inv.expires_at <= now() or v_inv.used_count >= v_inv.max_uses then
    raise exception 'Invitation expired, revoked or unavailable' using errcode = '42501';
  end if;
  if v_inv.kind = 'email' and v_verified_email <> v_inv.invited_email then
    raise exception 'Use the email address specified in this invitation' using errcode = '42501';
  end if;

  insert into public.trip_members (trip_id, user_id, role)
  values (v_inv.trip_id, v_user_id, v_inv.role)
  on conflict (trip_id, user_id) do nothing;
  get diagnostics v_inserted_count = row_count;
  if v_inserted_count = 1 then
    update public.trip_invitations set used_count = used_count + 1 where id = v_inv.id;
  end if;
  return v_inv.trip_id;
end;
$$;

-- Owners see members' email addresses; editors/viewers only see roles and IDs.
-- No direct SELECT on auth.users is granted to authenticated users.
create function public.list_trip_members(p_trip_id uuid)
returns table (
  user_id uuid,
  role public.trip_member_role,
  joined_at timestamptz,
  email text
) language plpgsql stable security definer set search_path = '' as $$
begin
  if (select auth.uid()) is null or not private.is_trip_member(p_trip_id) then
    raise exception 'Not authorized to view members' using errcode = '42501';
  end if;
  return query
    select m.user_id, m.role, m.joined_at,
      case when private.is_trip_owner(p_trip_id) then u.email::text else null::text end
    from public.trip_members m
    join auth.users u on u.id = m.user_id
    where m.trip_id = p_trip_id
    order by case when m.role = 'owner' then 0 else 1 end, m.joined_at, m.user_id;
end;
$$;

-- Owner can view active and past invitation metadata without the secret hashes.
create function public.list_trip_invitations(p_trip_id uuid)
returns table (
  id uuid,
  kind text,
  role public.trip_member_role,
  invited_email text,
  expires_at timestamptz,
  max_uses integer,
  used_count integer,
  revoked_at timestamptz,
  created_at timestamptz,
  active boolean
) language plpgsql stable security definer set search_path = '' as $$
begin
  if (select auth.uid()) is null or not private.is_trip_owner(p_trip_id) then
    raise exception 'Only the trip owner can view invitations' using errcode = '42501';
  end if;
  return query
    select i.id, i.kind, i.role, i.invited_email, i.expires_at,
      i.max_uses, i.used_count, i.revoked_at, i.created_at,
      (i.revoked_at is null and i.expires_at > now() and i.used_count < i.max_uses)
    from public.trip_invitations i
    where i.trip_id = p_trip_id
    order by i.created_at desc limit 50;
end;
$$;

create function public.revoke_trip_invitation(p_trip_id uuid, p_invitation_id uuid)
returns void language plpgsql security definer set search_path = '' as $$
begin
  if (select auth.uid()) is null or not private.is_trip_owner(p_trip_id) then
    raise exception 'Only the trip owner can revoke invitations' using errcode = '42501';
  end if;
  update public.trip_invitations set revoked_at = now()
  where id = p_invitation_id and trip_id = p_trip_id and revoked_at is null;
  if not found then
    raise exception 'Invitation not available' using errcode = '42501';
  end if;
end;
$$;

create function public.set_trip_member_role(
  p_trip_id uuid, p_user_id uuid, p_role text
)
returns void language plpgsql security definer set search_path = '' as $$
begin
  if (select auth.uid()) is null or not private.is_trip_owner(p_trip_id) then
    raise exception 'Only the trip owner can manage roles' using errcode = '42501';
  end if;
  if p_role is null or p_role not in ('editor', 'viewer') then
    raise exception 'Invalid member role' using errcode = '22023';
  end if;
  -- The sole Owner membership can never be reassigned or changed by this RPC.
  update public.trip_members set role = p_role::public.trip_member_role
  where trip_id = p_trip_id and user_id = p_user_id and role <> 'owner';
  if not found then
    raise exception 'Member not available for role change' using errcode = '42501';
  end if;
end;
$$;

create function public.remove_trip_member(p_trip_id uuid, p_user_id uuid)
returns void language plpgsql security definer set search_path = '' as $$
begin
  if (select auth.uid()) is null or
    (not private.is_trip_owner(p_trip_id) and (select auth.uid()) <> p_user_id) then
    raise exception 'Not authorized to remove this member' using errcode = '42501';
  end if;
  -- Owners cannot be removed, including by themselves.
  delete from public.trip_members
  where trip_id = p_trip_id and user_id = p_user_id and role <> 'owner';
  if not found then
    raise exception 'Member not available for removal' using errcode = '42501';
  end if;
end;
$$;

-- Public RPCs are reachable by any authenticated client, but authorization is
-- independently enforced IN EACH function. No browser table write grants.
revoke all on function public.create_trip_invitation(uuid,text,text,text,text) from public, anon;
revoke all on function public.accept_trip_invitation(text) from public, anon;
revoke all on function public.list_trip_members(uuid) from public, anon;
revoke all on function public.list_trip_invitations(uuid) from public, anon;
revoke all on function public.revoke_trip_invitation(uuid,uuid) from public, anon;
revoke all on function public.set_trip_member_role(uuid,uuid,text) from public, anon;
revoke all on function public.remove_trip_member(uuid,uuid) from public, anon;

grant execute on function public.create_trip_invitation(uuid,text,text,text,text) to authenticated;
grant execute on function public.accept_trip_invitation(text) to authenticated;
grant execute on function public.list_trip_members(uuid) to authenticated;
grant execute on function public.list_trip_invitations(uuid) to authenticated;
grant execute on function public.revoke_trip_invitation(uuid,uuid) to authenticated;
grant execute on function public.set_trip_member_role(uuid,uuid,text) to authenticated;
grant execute on function public.remove_trip_member(uuid,uuid) to authenticated;

comment on table public.trip_invitations is
  'M5 invitations contain SHA-256 token hashes only; raw invitation links never enter this table.';

commit;
